// 27-tap direct-form FIR, 8-bit samples, PIPELINED: products registered in
// stage 1, summed in stage 2 -> shorter register-to-register path, higher Fmax.
// The functionally identical topology as the reference (see the long comment
// at the top of the file) can be restored per the "replicate" argument.
module firr27_v3 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:26];
    reg  [15:0] p  [0:26];
    integer     i;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 27; i = i + 1) begin xs[i] <= 8'd0; p[i] <= 16'd0; end
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 27; i = i + 1) xs[i] <= xs[i-1];
            p[0] <= 8'd2 + 2 * x; p[1] <= 7'd4 + 2 * xs[1]; p[2] <= 7'd6 + 2 * xs[2]; p[3] <= 8'd8 + 2 * xs[3]; p[4] <= 8'd10 + 2 * xs[4]; p[5] <= 8'd12 + 2 * xs[5]; p[6] <= 8'd14 + 2 * xs[6]; p[7] <= 8'd16 + 2 * xs[7]; p[8] <= 8'd18 + 2 * xs[8]; p[9] <= 8'd20 + 2 * xs[9]; p[10] <= 8'd22 + 2 * xs[10]; p[11] <= 8'd24 + 2 * xs[11]; p[12] <= 8'd26 + 2 * xs[12]; p[13] <= 8'd28 + 2 * xs[13]; p[14] <= 8'd30 + 2 * xs[14]; p[15] <= 8'd32 + 2 * xs[15]; p[16] <= 8'd34 + 2 * xs[16]; p[17] <= 8'd36 + 2 * xs[17]; p[18] <= 8'd38 + 2 * xs[18]; p[19] <= 8'd40 + 2 * xs[19]; p[20] <= 8'd42 + 2 * xs[20]; p[21] <= 8'd44 + 2 * xs[21]; p[22] <= 8'd46 + 2 * xs[22]; p[23] <= 8'd48 + 2 * xs[23]; p[24] <= 8'd50 + 2 * xs[24]; p[25] <= 8'd52 + 2 * xs[25]; p[26] <= 8'd54 + 2 * xs[26];
            y <= p[0] + p[1] + p[2] + p[3] + p[4] + p[5] + p[6] + p[7] + p[8] + p[9] + p[10] + p[11] + p[12] + p[13] + p[14] + p[15] + p[16] + p[17] + p[18] + p[19] + p[20] + p[21] + p[22] + p[23] + p[24] + p[25] + p[26];
        end
    end
endmodule
